arguments.new_string:
/* Divider line */
.section-divider {
  height: 1px;
  background: var(--border);
  margin: 0;
}

/* ============================================================
   MOBILE POLISH — FINAL OVERRIDES
   ============================================================ */

/* Ensure hero eyebrow is centered block on mobile */
@media (max-width: 768px) {
  .hero-content {
    display: flex;
    flex-direction: column;
    align-items: center;
  }

  .hero-eyebrow {
    align-self: center;
  }

  .hero h1,
  .hero .typewriter,
  .hero p {
    text-align: center;
    width: 100%;
  }

  /* Prevent carousel from creating horizontal scroll */
  .projects .container {
    overflow: hidden;
  }

  /* Skills: Bootstrap col override for mobile */
  .skills .col-lg-3,
  .skills .col-md-4,
  .skills .col-sm-6 {
    flex: 0 0 33.333%;
    max-width: 33.333%;
  }

  /* Make contact form row stack properly */
  .contact-form .row .col-md-6 {
    flex: 0 0 100%;
    max-width: 100%;
  }

  /* Reduce section padding for mobile */
  .stats { padding: 2.5rem 0; }

  /* Position badge label styling */
  .achievement-badge {
    font-size: 0.68rem;
    padding: 0.2rem 0.55rem;
  }

  /* Ensure all images are contained */
  img {
    max-width: 100%;
    height: auto;
  }
}

@media (max-width: 480px) {
  /* Very small phones */
  .hero h1 {
    font-size: 1.75rem;
  }

  .hero .typewriter {
    font-size: 0.78rem;
  }

  .hero p {
    font-size: 0.85rem;
  }

  .hero-buttons .btn-primary,
  .hero-buttons .btn-outline-light,
  .hero-buttons .btn-resume {
    max-width: 100%;
    font-size: 0.85rem;
    padding: 0.65rem 1.2rem;
  }

  /* Skills: 2 columns on very small phones */
  .skills .col-lg-3,
  .skills .col-md-4,
  .skills .col-sm-6 {
    flex: 0 0 50%;
    max-width: 50%;
  }

  .skill-item {
    padding: 1rem 0.5rem;
  }

  .skill-icon {
    font-size: 1.4rem;
    margin-bottom: 0.5rem;
  }

  .skill-name {
    font-size: 0.68rem;
  }

  /* Stats: 2-col on very small */
  .stats-grid {
    grid-template-columns: 1fr 1fr;
  }

  .stat-box {
    padding: 1.25rem 0.75rem;
  }

  .stat-number {
    font-size: 1.8rem;
  }

  .stat-label {
    font-size: 0.72rem;
  }

  /* Project cards */
  .project-carousel {
    padding: 0 28px;
  }

  .project-content {
    padding: 1.1rem;
  }

  .project-content h4 {
    font-size: 0.85rem;
  }

  .project-tag {
    font-size: 0.65rem;
    padding: 0.15rem 0.45rem;
  }

  /* Article cards */
  .article-img,
  .media-img {
    height: 160px;
  }

  /* Achievement cards */
  .achievement-card {
    padding: 1.1rem 0.9rem;
  }

  /* Contact */
  .contact-form {
    padding: 1.25rem 0.9rem;
    border-radius: var(--radius-md);
  }

  .contact-item {
    padding: 0.75rem 0.85rem;
    gap: 0.75rem;
  }

  .contact-icon {
    width: 36px;
    height: 36px;
    font-size: 0.8rem;
  }

  /* Navbar */
  .navbar-brand {
    font-size: 1rem;
  }

  .navbar-collapse {
    padding: 0.75rem;
  }

  /* Section header on tiny screens */
  .section-header h2 {
    font-size: 1.5rem;
  }

  .section-label {
    font-size: 0.68rem;
  }

  /* Footer */
  .social-link {
    width: 36px;
    height: 36px;
  }

  .back-to-top {
    width: 34px;
    height: 34px;
    bottom: 1rem;
    right: 1rem;
    font-size: 0.75rem;
  }
}

