  display:flex; align-items:center; gap:0.5rem;
}
.pnav-brand::before { content:'⬡'; color:var(--accent); font-size:0.95rem; }

.pnav-back {
  display:inline-flex; align-items:center; gap:0.5rem;
  font-size:0.82rem; font-weight:600;
  color: var(--text-muted); text-decoration:none;
  border:1px solid var(--border);
  background: var(--bg-elevated);
  padding:0.4rem 0.9rem; border-radius:var(--radius-sm);
  transition: var(--transition);
  letter-spacing:0.02em;
}
.pnav-back:hover {
  color:var(--accent); border-color:var(--border-hover);
  background:var(--accent-dim);
}

.pnav-right {
  display:flex; align-items:center; gap:0.5rem;
}

.ptheme-switcher {
  display:flex; align-items:center; gap:0.2rem;
  padding:0.2rem; background:var(--bg-elevated);
  border:1px solid var(--border); border-radius:var(--radius-md);
}

.ptheme-btn {
  background:none; border:none; cursor:pointer;
  color:var(--text-muted); font-size:0.82rem;
  width:30px; height:30px; border-radius:var(--radius-sm);
  display:flex; align-items:center; justify-content:center;
  transition:var(--transition);
}
.ptheme-btn:hover { color:var(--text); background:var(--border); }
.ptheme-btn.active { background:var(--accent-dim); color:var(--accent); }

/* ── Hero ───────────────────────────────────────────────────── */
.p-hero {
  padding: 6.5rem 0 3.5rem;
  position:relative; overflow:hidden;
  background: var(--bg);
}

.p-hero::before {
  content:'';
  position:absolute; top:-15%; right:-5%;
  width:550px; height:550px;
  background: radial-gradient(circle, rgba(56,189,248,0.05) 0%, transparent 70%);
  pointer-events:none;
}
.p-hero::after {
  content:'';
  position:absolute; bottom:-15%; left:-5%;
  width:400px; height:400px;
  background: radial-gradient(circle, rgba(129,140,248,0.04) 0%, transparent 70%);
  pointer-events:none;
}

.p-eyebrow {
  display:inline-flex; align-items:center; gap:0.5rem;
  font-size:0.72rem; font-weight:600; letter-spacing:0.1em;
  text-transform:uppercase; color:var(--accent);
  border:1px solid var(--border-hover); background:var(--accent-dim);
  padding:0.35rem 0.9rem; border-radius:999px;
  margin-bottom:1.25rem;
}

.p-title {
  font-family: 'Space Grotesk', 'Inter', sans-serif;
  font-size: clamp(1.8rem, 4vw, 2.9rem);
  font-weight:700; letter-spacing:-0.035em; line-height:1.1;
  color:var(--text); margin-bottom:1rem;
}

.p-subtitle {
  font-size:1rem; color:var(--text-subtle);
  max-width:560px; line-height:1.75; margin-bottom:1.75rem;
}

/* ── Link Buttons ───────────────────────────────────────────── */
.p-links { display:flex; flex-wrap:wrap; gap:0.75rem; margin-bottom:0; }

.link-btn {
  display:inline-flex; align-items:center; gap:0.5rem;
  background:var(--bg-elevated); border:1px solid var(--border);
  color:var(--text-subtle) !important; text-decoration:none;
  padding:0.6rem 1.2rem; border-radius:var(--radius-sm);
  font-size:0.85rem; font-weight:500; letter-spacing:0.01em;
  transition:var(--transition);
}
.link-btn:hover {
  border-color:var(--border-hover); color:var(--accent) !important;
  background:var(--accent-dim); transform:translateY(-2px);
}

/* ── Timeline Info ──────────────────────────────────────────── */
.timeline-info {
  background:var(--bg-card); border:1px solid var(--border);
  border-left: 3px solid var(--accent);
  border-radius:var(--radius-md); padding:1.25rem 1.5rem;
  margin:1.25rem 0;
}
.timeline-info p { color:var(--text-subtle); font-size:0.88rem; margin-bottom:0.5rem; }
.timeline-info p:last-child { margin-bottom:0; }
.timeline-info strong { color:var(--text); }
.timeline-info i { color:var(--accent); }

/* ── Skill Badges ───────────────────────────────────────────── */
#skills-container {
  display:flex; flex-wrap:wrap; gap:0.5rem;
}

.skill-badge {
  font-family: 'JetBrains Mono', monospace;
  background:var(--bg-elevated); border:1px solid var(--border);
  color:var(--text-subtle); padding:0.25rem 0.7rem;
  border-radius:4px; font-size:0.78rem; font-weight:500;
  letter-spacing:0.02em;
  opacity:0; transform:translateY(12px);
  transition: opacity 0.35s ease, transform 0.35s ease,
              border-color 0.25s, color 0.25s, background 0.25s;
}
.skill-badge.visible { opacity:1; transform:translateY(0); }
.skill-badge:hover {
  border-color:var(--border-hover); color:var(--accent);
  background:var(--accent-dim);
}

/* ── Main Content Card ──────────────────────────────────────── */
.p-body { max-width:1200px; margin:0 auto; padding:0 1.5rem 4rem; }

.project-card {
  background:var(--bg-card); border:1px solid var(--border);
  border-radius:var(--radius-lg); overflow:hidden;
  margin-bottom:2rem; position:relative;
  transition:var(--transition);
}
.project-card > .p-card-inner { padding:2.5rem; }

/* Top accent line */
.project-card::before {
  content:''; position:absolute; top:0; left:0; right:0; height:2px;
  background:var(--gradient-h);
}

/* ── Carousel ───────────────────────────────────────────────── */
.carousel-container {
  border-radius:var(--radius-md); overflow:hidden;
  border:1px solid var(--border);
  background:var(--bg-elevated);
}

.carousel-item {
  height:360px; background:var(--bg-elevated);
}
.carousel-item img {
  width:100%; height:100%; object-fit:cover;
  filter:saturate(0.88);
  transition:filter 0.4s;
}
.carousel-item.active img { filter:saturate(1); }

.carousel-control-prev,
.carousel-control-next {
  width:40px; height:40px;
  background:rgba(10,14,23,0.6);
  backdrop-filter:blur(8px);
  border:1px solid var(--border);
  border-radius:50%;
  top:50%; transform:translateY(-50%);
  opacity:0; transition:var(--transition);
}
.carousel-container:hover .carousel-control-prev,
.carousel-container:hover .carousel-control-next { opacity:1; }

.carousel-control-prev { left:10px; }
.carousel-control-next { right:10px; }

/* ── Section Titles ─────────────────────────────────────────── */
.section-title {
  font-family:'Space Grotesk','Inter',sans-serif;
  font-size:1.1rem; font-weight:700; letter-spacing:-0.01em;
  color:var(--text); margin:2rem 0 1rem;
  display:flex; align-items:center; gap:0.6rem;
}
.section-title::before {
  content:'';
  display:inline-block; width:3px; height:1.1em;
  background:var(--gradient); border-radius:2px; flex-shrink:0;
}

/* ── Tech Specs ─────────────────────────────────────────────── */
.tech-specs {
  display:grid;
  grid-template-columns:repeat(auto-fill, minmax(180px, 1fr));
  gap:1rem; margin-top:1rem;
}

.spec-card {
  background:var(--bg-elevated); border:1px solid var(--border);
  border-radius:var(--radius-md); padding:1.25rem 1rem;
  text-align:center; transition:var(--transition);
}
.spec-card:hover {
  border-color:var(--border-hover);
  transform:translateY(-4px);
  background:var(--accent-dim);
}
.spec-icon {
  font-size:1.5rem; color:var(--accent);
  margin-bottom:0.6rem; display:block;
}
.spec-card h5 {
  font-family:'Space Grotesk','Inter',sans-serif;
  font-size:0.82rem; font-weight:600;
  color:var(--text-subtle); letter-spacing:0.04em;
  text-transform:uppercase; margin-bottom:0.35rem;
}
.spec-card p {
  font-size:0.88rem; color:var(--text); margin:0;
  font-weight:500;
}

/* ── Progress Bars ──────────────────────────────────────────── */
.progress-container { margin-bottom:1rem; }
.progress-label {
  display:flex; justify-content:space-between;
  font-size:0.82rem; font-weight:500;
  color:var(--text-subtle); margin-bottom:0.4rem;
}
.progress-label span:last-child { color:var(--accent); font-weight:600; }
.progress {
  height:6px; background:var(--bg-elevated);
  border-radius:999px; overflow:hidden;
  border:1px solid var(--border);
}
.progress-bar {
  height:100%; background:var(--gradient-h);
  border-radius:999px;
}

/* ── Feature Highlights ─────────────────────────────────────── */
.feature-highlight {
  display:flex; align-items:flex-start; gap:1rem;
  padding:1rem 1.1rem; margin-bottom:0.75rem;
  background:var(--bg-elevated); border:1px solid var(--border);
  border-radius:var(--radius-md); transition:var(--transition);
}
.feature-highlight:hover {
  border-color:var(--border-hover);
  transform:translateX(4px);
}
.feature-icon {
  width:40px; height:40px; flex-shrink:0;
  border-radius:var(--radius-sm); border:1px solid var(--border-hover);
  background:var(--accent-dim); color:var(--accent);
  display:flex; align-items:center; justify-content:center;
  font-size:1rem;
}
.feature-highlight h5 {
  font-family:'Space Grotesk','Inter',sans-serif;
  font-size:0.9rem; font-weight:600; margin-bottom:0.25rem;
  color:var(--text); letter-spacing:-0.01em;
}
.feature-highlight p { font-size:0.83rem; color:var(--text-muted); margin:0; }

/* ── Learning Items ─────────────────────────────────────────── */
.learning-item {
  padding:1rem 1.1rem; margin-bottom:0.75rem;
  background:var(--bg-elevated); border:1px solid var(--border);
  border-left:3px solid var(--indigo);
  border-radius:var(--radius-md); transition:var(--transition);
}
.learning-item:hover {
  border-color:var(--indigo);
  border-left-color:var(--indigo);
  transform:translateX(4px);
}
.learning-item h5 {
  font-family:'Space Grotesk','Inter',sans-serif;
  font-size:0.9rem; font-weight:600; margin-bottom:0.3rem;
  color:var(--text);
}
.learning-item p { font-size:0.83rem; color:var(--text-muted); margin:0; }

/* ── Target Audience / Applications ────────────────────────── */
.target-audience { list-style:none; padding:0; }
.target-audience li {
  display:flex; align-items:flex-start; gap:0.75rem;
  font-size:0.88rem; color:var(--text-subtle);
  padding:0.85rem 1rem; margin-bottom:0.5rem;
  background:var(--bg-elevated); border:1px solid var(--border);
  border-radius:var(--radius-md); transition:var(--transition);
  line-height:1.55;
}
.target-audience li:hover {
  border-color:var(--border-hover); transform:translateX(3px);
  background:var(--accent-dim);
}
.bullet { font-size:1em; flex-shrink:0; }

/* ── Award Badge ────────────────────────────────────────────── */
.award-badge {
  display:inline-flex; align-items:center; gap:0.5rem;
  background:var(--bg-elevated); border:1px solid rgba(251,191,36,0.3);
  color:#FBBF24; padding:0.6rem 1.1rem; border-radius:var(--radius-md);
  font-size:0.88rem; font-weight:600; margin:0.35rem 0;
}

/* ── Video ──────────────────────────────────────────────────── */
.project-video {
  border-radius:var(--radius-lg); overflow:hidden;
  border:1px solid var(--border); margin:2rem 0;
  background:var(--bg-elevated);
}

/* ── Footer ─────────────────────────────────────────────────── */
.p-footer {
  background:var(--bg-card); border-top:1px solid var(--border);
  padding:2.5rem 1.5rem; text-align:center;
}
.p-footer p { color:var(--text-muted); font-size:0.82rem; margin:0; }
.p-footer a { color:var(--accent); text-decoration:none; }
.p-footer a:hover { text-decoration:underline; }

/* ── Back to Top ────────────────────────────────────────────── */
.back-btn {
  position:fixed; bottom:1.75rem; right:1.75rem; z-index:999;
  width:42px; height:42px; border-radius:var(--radius-sm);
  background:var(--bg-elevated); border:1px solid var(--border);
  color:var(--text-muted); text-decoration:none;
  display:flex; align-items:center; justify-content:center;
  font-size:0.85rem; transition:var(--transition);
  opacity:0; visibility:hidden; transform:translateY(8px);
}
.back-btn:hover {
  background:var(--accent-dim); border-color:var(--border-hover);
  color:var(--accent);
}
.back-btn.active {
  opacity:1; visibility:visible; transform:translateY(0);
}

/* ── Scroll Animations ──────────────────────────────────────── */
.fade-in {
  opacity:0; transform:translateY(22px);
  transition: opacity 0.65s cubic-bezier(0.4,0,0.2,1),
              transform 0.65s cubic-bezier(0.4,0,0.2,1);
}
.fade-in.visible { opacity:1; transform:translateY(0); }
.delay-1 { transition-delay:0.1s; }
.delay-2 { transition-delay:0.2s; }
.delay-3 { transition-delay:0.3s; }
.delay-4 { transition-delay:0.4s; }

/* ── Responsive ─────────────────────────────────────────────── */
@media (max-width: 991px) {
  .project-card > .p-card-inner { padding:2rem 1.5rem; }
  .p-hero { padding:5.5rem 0 2.5rem; }
}

@media (max-width: 768px) {
  .p-hero { padding:5rem 0 2rem; }
  .p-title { font-size:clamp(1.5rem, 7vw, 2rem); }
  .carousel-item { height:240px; }
  .p-links { flex-direction:column; }
  .link-btn { justify-content:center; }
  .tech-specs { grid-template-columns:repeat(2, 1fr); }
  .pnav-inner { padding:0.75rem 1rem; }
  .p-body { padding:0 1rem 3rem; }
  .project-card > .p-card-inner { padding:1.5rem 1rem; }
  .back-btn { bottom:1.2rem; right:1.2rem; }
}

@media (max-width: 480px) {
  .p-title { font-size:1.5rem; }
  .carousel-item { height:200px; }
  .tech-specs { grid-template-columns:1fr 1fr; }
  .pnav-brand span { display:none; }
}

import os
import re

PROJECT_DIR = "project"

NEW_HEAD_LINKS = """\
  <link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css" rel="stylesheet">
  <link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css" rel="stylesheet">
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600&family=Space+Grotesk:wght@500;600;700&family=JetBrains+Mono:wght@400;500&display=swap" rel="stylesheet">
  <link rel="stylesheet" href="../assets/css/project.css">"""

NEW_NAVBAR = """\
  <!-- Navbar -->
  <nav class="pnav" id="pnav">
    <div class="pnav-inner">
      <a href="../index.html" class="pnav-brand">
        <span>Darshit Vaghani</span>
      </a>
      <div class="pnav-right">
        <a href="../index.html#projects" class="pnav-back">
          <i class="fas fa-arrow-left"></i> Portfolio
        </a>
        <div class="ptheme-switcher" id="pthemeSwitcher">
          <button class="ptheme-btn" data-theme-val="dark" title="Dark"><i class="fas fa-moon"></i></button>
          <button class="ptheme-btn" data-theme-val="light" title="Light"><i class="fas fa-sun"></i></button>
          <button class="ptheme-btn" data-theme-val="electric" title="Electric"><i class="fas fa-bolt"></i></button>
        </div>
      </div>
    </div>
  </nav>"""

NEW_FOOTER = """\
  <!-- Footer -->
  <footer class="p-footer">
    <div class="container">
      <p>&copy; 2024 <a href="../index.html">Darshit Vaghani</a> &mdash; IoT &amp; Embedded Systems Engineer</p>
    </div>
  </footer>"""

NEW_BACK_BTN = """\
  <a href="#" class="back-btn" id="backToTop" title="Back to top">
    <i class="fas fa-arrow-up"></i>
  </a>"""

NEW_SCRIPTS = """\
  <script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/js/bootstrap.bundle.min.js"></script>
  <script>
    // ── Theme sync with main portfolio ──────────────────────
    const body = document.body;
    const switcher = document.getElementById('pthemeSwitcher');
    const savedTheme = localStorage.getItem('portfolio-theme') || 'dark';
    body.setAttribute('data-theme', savedTheme);

    function setTheme(t) {
      body.setAttribute('data-theme', t);
      localStorage.setItem('portfolio-theme', t);
      document.querySelectorAll('.ptheme-btn').forEach(b => {
        b.classList.toggle('active', b.dataset.themeVal === t);
      });
    }
    setTheme(savedTheme);

    switcher.addEventListener('click', e => {
      const btn = e.target.closest('.ptheme-btn');
      if (btn) setTheme(btn.dataset.themeVal);
    });

    // ── Navbar scroll class ──────────────────────────────────
    const nav = document.getElementById('pnav');
    window.addEventListener('scroll', () => {
      nav.classList.toggle('scrolled', window.scrollY > 40);
      document.getElementById('backToTop').classList.toggle('active', window.scrollY > 300);
    });

    // ── Skill badges stagger ─────────────────────────────────
    document.querySelectorAll('.skill-badge').forEach((el, i) => {
      setTimeout(() => el.classList.add('visible'), i * 120);
    });

    // ── IntersectionObserver fade-in ─────────────────────────
    const io = new IntersectionObserver((entries) => {
      entries.forEach(e => {
        if (e.isIntersecting) {
          e.target.classList.add('visible');
          io.unobserve(e.target);
        }
      });
    }, { threshold: 0.1, rootMargin: '0px 0px -50px 0px' });

    document.querySelectorAll('.fade-in').forEach(el => io.observe(el));
  </script>"""


def transform_file(filepath):
    with open(filepath, 'rb') as f:
        raw = f.read()

    # Normalise line endings to LF for processing
    content = raw.decode('utf-8', errors='replace').replace('\r\n', '\n').replace('\r', '\n')

    # 1. Remove ALL existing link/style tags from <head> and replace with new ones
    #    Strategy: remove old Poppins/Roboto font links
    content = re.sub(
        r'<link[^>]*(poppins|roboto.mono|fonts\.googleapis\.com|fonts\.gstatic\.com|preconnect)[^>]*>\s*',
        '', content, flags=re.IGNORECASE
    )
    #    Remove Bootstrap link (we'll re-add in our block)
    content = re.sub(r'<link[^>]*bootstrap[^>]*>\s*', '', content, flags=re.IGNORECASE)
    #    Remove Font Awesome link
    content = re.sub(r'<link[^>]*font-awesome[^>]*>\s*', '', content, flags=re.IGNORECASE)
    #    Remove the big inline <style>...</style> block
    content = re.sub(r'<style>.*?</style>', '', content, flags=re.DOTALL)
    #    Remove existing project.css link if any
    content = re.sub(r'<link[^>]*project\.css[^>]*>\s*', '', content, flags=re.IGNORECASE)

    # 2. Insert new head links right after <meta viewport> tag
    content = re.sub(
        r'(<meta[^>]*viewport[^>]*>)',
        r'\1\n' + NEW_HEAD_LINKS,
        content, flags=re.IGNORECASE
    )

    # 3. Replace navbar block entirely
    content = re.sub(
        r'<!--\s*(?:Circuit Elements|Navigation|Navbar).*?-->.*?</nav>',
        NEW_NAVBAR,
        content, flags=re.DOTALL | re.IGNORECASE
    )
    # Fallback: if nav exists but no comment marker
    if '<nav ' in content and 'pnav' not in content:
        content = re.sub(r'<nav\b[^>]*>.*?</nav>', NEW_NAVBAR, content, flags=re.DOTALL)

    # 4. Replace footer block
    content = re.sub(
        r'<footer\b[^>]*>.*?</footer>',
        NEW_FOOTER,
        content, flags=re.DOTALL | re.IGNORECASE
    )

    # 5. Replace old back-btn anchor
    content = re.sub(
        r'<a\s[^>]*class="back-btn"[^>]*>.*?</a>',
        NEW_BACK_BTN,
        content, flags=re.DOTALL | re.IGNORECASE
    )

    # 6. Remove circuit element divs (decorative, not needed)
    content = re.sub(
        r'<!--\s*Circuit Elements\s*-->.*?(?=\s*<!--)',
        '',
        content, flags=re.DOTALL | re.IGNORECASE
    )
    content = re.sub(r'<div class="circuit-element[^"]*"[^>]*></div>\s*', '', content)

    # 7. Replace the <script> block(s) at end of body
    #    Remove Bootstrap JS + all inline scripts
    content = re.sub(
        r'<script src="[^"]*bootstrap[^"]*"[^>]*></script>\s*',
        '',
        content, flags=re.IGNORECASE
    )
    content = re.sub(r'<script>\s*//.*?</script>', '', content, flags=re.DOTALL)
    content = re.sub(r'<script>.*?</script>', '', content, flags=re.DOTALL)

    # 8. Insert new scripts block before </body>
    content = content.replace('</body>', NEW_SCRIPTS + '\n</body>')

    # 9. Wrap the main content container (after nav) in the p-body div if not already
    #    Add the p-body wrapper around the container + project card area
    # Only do this if it doesn't already have p-body
    if 'class="p-body"' not in content:
        # Find where hero-section ends and wrap subsequent container divs
        content = re.sub(
            r'(</section>)\s*(\s*<!-- Project Showcase -->)',
            r'\1\n  <div class="p-body">\2',
            content, flags=re.DOTALL
        )
        # Close p-body before footer
        content = content.replace('  <!-- Footer -->', '  </div>\n\n  <!-- Footer -->')

    # 10. Fix the hero-section class naming for our CSS
    #     Rename <section class="hero-section"> to <section class="p-hero">
    content = content.replace('class="hero-section"', 'class="p-hero"')

    # 11. Wrap project-card content in p-card-inner if not there
    content = re.sub(
        r'(<div class="project-card)\s*(p-4\s*p-md-5")',
        r'\1"',
        content
    )
    content = re.sub(
        r'(<div class="project-card">)',
        r'\1\n      <div class="p-card-inner">',
        content
    )

    # 12. Clean up excessive blank lines
    content = re.sub(r'\n{4,}', '\n\n', content)

    # Write back with LF endings
    with open(filepath, 'wb') as f:
        f.write(content.encode('utf-8'))

    print(f"  ✓  {os.path.basename(filepath)}")


def main():
    files = sorted([f for f in os.listdir(PROJECT_DIR) if f.endswith('.html')])
    print(f"Transforming {len(files)} project files...\n")
    for fname in files:
        fpath = os.path.join(PROJECT_DIR, fname)
        try:
            transform_file(fpath)
        except Exception as e:
            print(f"  ✗  {fname}: {e}")
    print(f"\nDone! {len(files)} files updated.")


