    margin-right: auto;
    max-width: 100%;
  }

  /* Hero buttons — stack vertically and center */
  .hero-buttons {
    flex-direction: column;
    align-items: center;
    width: 100%;
    gap: 0.7rem;
  }

  .hero-buttons .btn-primary,
  .hero-buttons .btn-outline-light,
  .hero-buttons .btn-resume {
    width: 100%;
    max-width: 300px;
    justify-content: center;
    text-align: center;
  }

  /* Stats */
  .stats { padding: 2.5rem 0; }

  .stats-grid {
    grid-template-columns: 1fr 1fr;
  }

  .stat-box {
    border-right: none;
    border-bottom: 1px solid var(--border);
    padding: 1.4rem 1rem;
  }

  .stat-box:nth-child(odd) {
    border-right: 1px solid var(--border);
  }

  .stat-box:last-child {
    border-bottom: none;
  }

  .stat-box:last-child:nth-child(odd) {
    grid-column: 1 / -1;
    border-right: none;
  }

  .stat-number { font-size: 2rem; }
  .stat-label { font-size: 0.78rem; }

  /* Project carousel */
  .project-carousel { padding: 0 36px; }
  .project-slide { min-width: 100%; }
  .carousel-button { width: 30px; height: 30px; font-size: 0.7rem; }

  /* Project card */
  .project-img { height: 170px; }
  .project-content { padding: 1.1rem; }
  .project-content h4 { font-size: 0.88rem; }

  /* Skills — 3 col on tablet/mobile */
  .skills .row > [class*="col-"] {
    flex: 0 0 33.333%;
    max-width: 33.333%;
    padding-left: 0.4rem;
    padding-right: 0.4rem;
  }

  .skill-item {
    padding: 1.2rem 0.6rem;
  }

  .skill-icon { font-size: 1.6rem; margin-bottom: 0.5rem; }
  .skill-name { font-size: 0.72rem; }

  /* Achievements */
  .achievement-card { padding: 1.5rem 1.1rem; }
  .achievement-icon { width: 42px; height: 42px; font-size: 1.1rem; }
  .achievement-title { font-size: 0.92rem; }
  .achievement-desc { font-size: 0.82rem; }
  .achievement-badge { font-size: 0.68rem; }

  /* Positions */
  .position-box {
    padding: 0.9rem 1rem;
    gap: 0.85rem;
  }

  .position-img { width: 44px; height: 44px; }
  .position-info h4 { font-size: 0.85rem; }
  .position-info p { font-size: 0.78rem; }

  /* Contact */
  .contact-form { padding: 1.5rem 1.1rem; border-radius: var(--radius-md); }

  /* Stack the Name + Email fields vertically */
  .contact-form .row > .col-md-6 {
    flex: 0 0 100%;
    max-width: 100%;
  }

  .contact-info { padding-left: 0; margin-top: 1.5rem; }
  .contact-item { padding: 0.85rem 1rem; }
  .contact-icon { width: 36px; height: 36px; font-size: 0.82rem; }

  /* Media / Article cards */
  .article-img,
  .media-img { height: 170px; }

  /* Footer */
  .social-links { gap: 0.55rem; }
  .social-link { width: 38px; height: 38px; font-size: 0.88rem; }

  /* Back to top */
  .back-to-top { bottom: 1.2rem; right: 1.2rem; width: 38px; height: 38px; }

  /* Prevent all horizontal overflow */
  * { max-width: 100%; }
  img, iframe, video { max-width: 100%; height: auto; }
  .project-img img,
  .article-img img,
  .media-img img { height: 100%; }
}

/* ── Small mobile (≤ 480px) ────────────────────────────────── */
@media (max-width: 480px) {
  section { padding: 2.75rem 0; }
  .container { padding-left: 0.9rem; padding-right: 0.9rem; }

  /* Navbar */
  .navbar-brand { font-size: 1rem; }
  .navbar { padding: 0.65rem 0; }

  /* Hero */
  .hero { padding-top: 72px; padding-bottom: 2.5rem; }
  .hero h1 { font-size: clamp(1.65rem, 10vw, 2rem); letter-spacing: -0.025em; }
  .hero .typewriter { font-size: 0.8rem; }
  .hero p { font-size: 0.85rem; }

  .hero-buttons .btn-primary,
  .hero-buttons .btn-outline-light,
  .hero-buttons .btn-resume {
    max-width: 100%;
    font-size: 0.85rem;
    padding: 0.65rem 1.2rem;
  }

  /* Stats */
  .stat-number { font-size: 1.8rem; }
  .stat-label { font-size: 0.72rem; }
  .stat-box { padding: 1.1rem 0.75rem; }

  /* Section header */
  .section-header h2 { font-size: clamp(1.35rem, 8vw, 1.75rem); }
  .section-label { font-size: 0.68rem; }

  /* Project carousel */
  .project-carousel { padding: 0 28px; }
  .project-img { height: 155px; }
  .project-tag { font-size: 0.65rem; padding: 0.15rem 0.45rem; }

  /* Skills — 2 cols on very small phones */
  .skills .row > [class*="col-"] {
    flex: 0 0 50%;
    max-width: 50%;
  }

  .skill-item { padding: 1rem 0.5rem; }
  .skill-icon { font-size: 1.4rem; }
  .skill-name { font-size: 0.68rem; }

  /* Achievement cards */
  .achievement-card { padding: 1.1rem 0.85rem; }

  /* Contact */
  .contact-form { padding: 1.1rem 0.85rem; }
  .contact-item { padding: 0.75rem 0.85rem; gap: 0.7rem; }
  .contact-icon { width: 32px; height: 32px; font-size: 0.78rem; }

  /* Article / media */
  .article-img, .media-img { height: 150px; }

  /* Footer */
  .social-link { width: 36px; height: 36px; }

  /* Back to top */
  .back-to-top { bottom: 1rem; right: 1rem; width: 34px; height: 34px; font-size: 0.75rem; }
}

/* ── Misc utilities ─────────────────────────────────────────── */
.text-accent { color: var(--accent); }
.monospace { font-family: \'JetBrains Mono\', monospace; font-size: 0.85em; }

.view-all-row {
  display: flex;
  justify-content: center;
  margin-top: 2.5rem;
}

.section-divider {
  height: 1px;
  background: var(--border);
  margin: 0;
}

/* Scrolled header */
header.scrolled {
  background: rgba(10, 14, 23, 0.97);
  box-shadow: 0 1px 0 var(--border);
}

[data-theme="light"] header.scrolled {
  background: rgba(248, 250, 252, 0.98);
}
'''

